// Ingest adapter (Java, snippet)
TweetEvent ev = mapper.readValue(req.body, TweetEvent.class);
validate(ev); // non-null tweet_id, text<=280, country ISO-2
ev.ts = Instant.parse(ev.created_at).toEpochMilli; ProducerRecord<String, byte> rec = new ProducerRecord<>( "tweets", // topic null, // key = null → random partition ev.ts, null, AVRO.serialize(ev)); // async send with 50ms timeout; on failure → disk spool
Future<RecordMetadata> fut = producer.send(rec, (meta, err) -> { if (err!= null) diskSpool.append(rec);
});
return Response.ok; // respond immediately — do NOT await fut

// Flink job DAG (Java)
DataStream<TweetEvent> tweets = env.fromSource(src, WatermarkStrategy.<TweetEvent>forBoundedOutOfOrderness(Duration.ofSeconds(10)).withTimestampAssigner((e, ts) -> e.ts).withIdleness(Duration.ofSeconds(30)), "kafka-tweets"); DataStream<Token> tokens = tweets.flatMap((ev, out) -> { for (String h: ev.hashtags) { out.collect(new Token(ev.country, h.toLowerCase, ev.ts)); }
}); tokens.keyBy(t -> t.country).window(SlidingEventTimeWindows.of(Time.minutes(5), Time.seconds(10))).process(new CmsTopKFunction) // next step.addSink(new RedisTrendingSink); // parallel fan-out

// CmsTopKFunction.processElement (per-token, Java)
final int D = 4, W = 1 << 20; // 4 rows × ~1M counters = 16 MB
int rows = this.cms; // flat d*w array in RocksDB-backed keyed state long subWinStart = (token.ts / 10_000) * 10_000;
SubCms sub = state.getOrCreate(subWinStart); // Conservative Update: only bump the row(s) currently at the min
int idx = new int[D];
int curMin = Integer.MAX_VALUE;
for (int r = 0; r < D; r++) { idx[r] = (int)(hash(token.hashtag, r) & (W - 1)); curMin = Math.min(curMin, sub.counters[r * W + idx[r]]);
}
for (int r = 0; r < D; r++) { if (sub.counters[r * W + idx[r]] == curMin) { sub.counters[r * W + idx[r]]++; }
}
int estimate = curMin + 1; // HeavyKeeper: probabilistic eviction inversely proportional to counter
heavyKeeper.offer(token.hashtag, estimate);

// RedisTrendingSink (Java, invoked by 10s ProcessingTimeTimer)
public void onTimer(long ts, OnTimerContext ctx) { String country = ctx.getCurrentKey; List<Topic> top = cmsState.mergedTopK(50); // merge ring of 30 → extract 50 TrendingPayload p = new TrendingPayload( country, ts, top, computeDeltas(top, previousTop)); try (Jedis r = pool.getResource) { r.set("trending:" + country, MAPPER.writeValueAsString(p)); r.set("trending:heartbeat", Long.toString(ts), SetParams.setParams.ex(30)); } previousTop = top;
}

// Client (TypeScript, React Native)
const res = await fetch(`https://api.twitter.com/v1/trending?country=US&limit=20`, { headers: { 'If-None-Match': lastEtag?? '', 'Accept-Encoding': 'br, gzip' }
});
if (res.status === 304) return; // nothing changed
const body = await res.json;
render(body.topics, body.generated_at);

// Client render + reschedule
setList(body.topics);
setUpdatedLabel(`updated ${secondsAgo(body.generated_at)}s ago`);
lastEtag = res.headers.get('etag'); const base = 45_000;
const jitter = base * 0.25 * (Math.random * 2 - 1);
const stale = Date.now - body.generated_at > 90_000;
const delay = stale? 10_000: base + jitter;
setTimeout(pollTrending, delay);
